use crate::store::Store;
use anyhow::{Context, Result, bail, ensure};
use base64::{Engine, engine::general_purpose::URL_SAFE_NO_PAD};
use reqwest::StatusCode;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::{
    fs,
    io::{BufRead, BufReader, Read, Write},
    net::TcpListener,
    path::Path,
    process::Command,
    time::{Duration, Instant},
};

pub const CONFIG_GUIDE: &str =
    "https://github.com/mizorewww/gdirect/blob/main/docs/configuration/README.md";
const TOKEN_URI: &str = "https://oauth2.googleapis.com/token";
const SCOPE: &str = "https://www.googleapis.com/auth/drive";

// Only these fields are kept, so an imported token_uri or credential source is ignored.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename = "authorized_user")]
pub struct Credentials {
    pub client_id: String,
    #[serde(default)]
    pub client_secret: String,
    pub refresh_token: String,
}
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Client {
    pub client_id: String,
    #[serde(default)]
    pub client_secret: String,
}
impl Credentials {
    pub fn parse(data: &[u8]) -> Result<Self> {
        let value: Value =
            serde_json::from_slice(data).context("credentials are not valid JSON")?;
        ensure!(
            value["type"] == "authorized_user",
            "expected authorized_user credentials, not a service account"
        );
        let credentials: Self = serde_json::from_value(value)
            .context("credentials are missing client_id or refresh_token")?;
        ensure!(
            !credentials.client_id.is_empty() && !credentials.refresh_token.is_empty(),
            "credentials are missing client_id or refresh_token"
        );
        Ok(credentials)
    }
    pub fn refresh_form(&self) -> [(&'static str, &str); 4] {
        [
            ("client_id", &self.client_id),
            ("client_secret", &self.client_secret),
            ("refresh_token", &self.refresh_token),
            ("grant_type", "refresh_token"),
        ]
    }
    pub fn client(&self) -> Client {
        Client {
            client_id: self.client_id.clone(),
            client_secret: [REDACTED],
        }
    }
}
pub fn credentials(db: &Store, account: Option<&str>) -> Result<Credentials> {
    if let Some(raw) = account.map(|a| db.credentials(a)).transpose()?.flatten() {
        return Credentials::parse(raw.as_bytes());
    }
    bail!(
        "first login requires a Desktop OAuth client JSON: gdirect login --client-secret PATH\nSetup: {CONFIG_GUIDE}"
    )
}
#[derive(Debug)]
pub struct Token {
    pub access_token: String,
    pub expires_in: i64,
}
fn http() -> Result<reqwest::blocking::Client> {
    Ok(crate::api::client_builder()
        .connect_timeout(Duration::from_secs(15))
        .timeout(Duration::from_secs(45))
        .redirect(reqwest::redirect::Policy::none())
        .build()?)
}
fn post_token(endpoint: &str, form: &[(&str, &str)]) -> Result<(StatusCode, Value)> {
    let response = http()?.post(endpoint).form(form).send().map_err(|e| {
        anyhow::anyhow!(
            "cannot reach Google's token endpoint ({}); check system HTTP/HTTPS proxy settings or HTTPS_PROXY and access to oauth2.googleapis.com",
            e.without_url()
        )
    })?;
    let status = response.status();
    let text = response.text().map_err(|e| e.without_url())?;
    Ok((status, serde_json::from_str(&text).unwrap_or_default()))
}
// Google's OAuth error code and description, e.g. "invalid_client: The OAuth client was deleted."
fn google_error(status: StatusCode, data: &Value) -> String {
    let code = data["error"].as_str().unwrap_or("unknown_error");
    match data["error_description"].as_str() {
        Some(description) => format!("{status} {code}: {description}"),
        None => format!("{status} {code}"),
    }
}
/// Whether a token-endpoint reply is Google's answer rather than some other page.
pub(crate) fn from_google(data: &Value) -> bool {
    data["access_token"].is_string() || data["error"].is_string()
}
pub(crate) fn refreshed(status: StatusCode, data: &Value) -> Result<Token> {
    if !status.is_success() {
        if data["error"] == "invalid_grant" {
            bail!("refresh credential expired or revoked; run gdirect login --reauth");
        }
        bail!(
            "Google token refresh failed ({}); run gdirect login --reauth",
            google_error(status, data)
        );
    }
    let access_token = data["access_token"]
        .as_str()
        .filter(|t| !t.is_empty() && t.bytes().all(|b| b.is_ascii_graphic()))
        .context("Google returned an invalid access token")?;
    Ok(Token {
        access_token: [REDACTED],
        expires_in: data["expires_in"].as_i64().unwrap_or(3600),
    })
}
pub fn refresh(credentials: &Credentials) -> Result<Token> {
    let (status, data) = post_token(TOKEN_URI, &credentials.refresh_form())?;
    refreshed(status, &data)
}
pub fn prepare_login(
    db: &Store,
    account: Option<&str>,
    client: Option<&Path>,
    import: Option<&Path>,
    reauth: bool,
) -> Result<Credentials> {
    if let Some(path) = import {
        return Credentials::parse(&fs::read(path).context("cannot read credentials JSON")?);
    }
    if let Some(path) = client {
        let data: Value =
            serde_json::from_slice(&fs::read(path).context("cannot read OAuth client JSON")?)?;
        ensure!(
            data["installed"].is_object(),
            "download a Desktop app OAuth client JSON (web clients are not supported)"
        );
        let client = serde_json::from_value(data["installed"].clone())
            .context("OAuth client JSON is missing client_id")?;
        return browser_login(&client);
    }
    if reauth {
        // Any signed-in account's client works for adding another account.
        let client = match db.setting("oauth_client")? {
            Some(raw) => serde_json::from_str(&raw)?,
            None => credentials(db, account.or(db.default_account()?.as_deref()))?.client(),
        };
        return browser_login(&client);
    }
    credentials(db, account)
}
fn random_string() -> Result<String> {
    let mut bytes = [0; 32];
    getrandom::fill(&mut bytes)
        .map_err(|_| anyhow::anyhow!("system random generator unavailable"))?;
    Ok(URL_SAFE_NO_PAD.encode(bytes))
}
fn challenge(verifier: &str) -> String {
    URL_SAFE_NO_PAD.encode(Sha256::digest(verifier.as_bytes()))
}
fn callback(target: &str, state: &str) -> Result<Option<String>> {
    ensure!(target.starts_with("/callback?"), "unexpected callback path");
    let url = url::Url::parse(&format!("http://127.0.0.1{target}"))?;
    let query: std::collections::HashMap<_, _> = url.query_pairs().into_owned().collect();
    ensure!(
        query.get("state").map(String::as_str) == Some(state),
        "OAuth state mismatch"
    );
    if query.contains_key("error") {
        return Ok(None);
    }
    Ok(Some(
        query
            .get("code")
            .filter(|s| !s.is_empty())
            .context("missing authorization code")?
            .clone(),
    ))
}
fn browser_login(client: &Client) -> Result<Credentials> {
    let client_id = client.client_id.as_str();
    ensure!(
        client_id.ends_with(".apps.googleusercontent.com"),
        "invalid Google OAuth client ID"
    );
    let secret = [REDACTED];
    let listener = TcpListener::bind(("127.0.0.1", 0))?;
    listener.set_nonblocking(true)?;
    let redirect = format!(
        "http://127.0.0.1:{}/callback",
        listener.local_addr()?.port()
    );
    let state = random_string()?;
    let verifier = random_string()?;
    let mut url = url::Url::parse("https://accounts.google.com/o/oauth2/v2/auth")?;
    url.query_pairs_mut().extend_pairs([
        ("client_id", client_id),
        ("redirect_uri", redirect.as_str()),
        ("response_type", "code"),
        ("scope", SCOPE),
        ("access_type", "offline"),
        ("prompt", "consent select_account"),
        ("state", state.as_str()),
        ("code_challenge", challenge(&verifier).as_str()),
        ("code_challenge_method", "S256"),
    ]);
    eprintln!("Open this URL in a browser on this computer:\n{url}");
    let mut browser = if cfg!(target_os = "macos") {
        Command::new("open")
    } else if cfg!(windows) {
        let mut c = Command::new("rundll32");
        c.arg("url.dll,FileProtocolHandler");
        c
    } else {
        Command::new("xdg-open")
    };
    let _ = browser
        .arg(url.as_str())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .spawn();
    let deadline = Instant::now() + Duration::from_secs(300);
    let code = loop {
        ensure!(
            Instant::now() < deadline,
            "browser login timed out; run the login command again"
        );
        let (mut stream, _) = match listener.accept() {
            Ok(s) => s,
            Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                std::thread::sleep(Duration::from_millis(100));
                continue;
            }
            Err(e) => return Err(e.into()),
        };
        stream.set_read_timeout(Some(Duration::from_secs(3)))?;
        let mut first = String::new();
        if BufReader::new(stream.try_clone()?.take(8192))
            .read_line(&mut first)
            .is_err()
        {
            continue;
        }
        let parts: Vec<_> = first.split_whitespace().collect();
        let result = if parts.first() == Some(&"GET") && parts.len() == 3 {
            callback(parts[1], &state)
        } else {
            Err(anyhow::anyhow!("invalid callback"))
        };
        let (status, body) = if result.is_ok() {
            (
                "200 OK",
                "Authorization received. Return to the terminal to finish login.",
            )
        } else {
            (
                "400 Bad Request",
                "Invalid authorization callback. Return to the login page.",
            )
        };
        let _ = write!(
            stream,
            "HTTP/1.1 {status}\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        if let Ok(code) = result {
            break code.context("Google authorization was declined")?;
        }
    };
    let (status, token) = post_token(
        TOKEN_URI,
        &[
            ("client_id", client_id),
            ("client_secret", secret),
            ("code", code.as_str()),
            ("code_verifier", verifier.as_str()),
            ("redirect_uri", redirect.as_str()),
            ("grant_type", "authorization_code"),
        ],
    )?;
    ensure!(
        status.is_success(),
        "Google rejected the authorization code ({}); verify the Desktop OAuth client configuration",
        google_error(status, &token)
    );
    let refresh_token = token["refresh_token"]
        .as_str()
        .filter(|s| !s.is_empty())
        .context("Google did not return a refresh token")?;
    Ok(Credentials {
        client_id: client_id.into(),
        client_secret: [REDACTED],
        refresh_token: [REDACTED],
    })
}
pub fn export_credentials(credentials: &Credentials, path: &Path) -> Result<()> {
    let mut options = fs::OpenOptions::new();
    options.write(true).create(true).truncate(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let mut file = options.open(path)?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        file.set_permissions(fs::Permissions::from_mode(0o600))?;
    }
    file.write_all(serde_json::to_string(credentials)?.as_bytes())?;
    Ok(())
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn token_exchange_uses_proxy() {
        crate::test_network::assert_route("auth::tests::token_exchange_uses_proxy", true, |url| {
            let (status, data) = post_token(url, &[("grant_type", "refresh_token")])?;
            ensure!(status.is_success(), "fixture token request failed");
            Ok(data)
        });
    }
    #[test]
    fn token_responses_keep_google_error_codes() {
        let token = refreshed(
            StatusCode::OK,
            &serde_json::json!({"access_token":"ya29.a","expires_in":3599}),
        )
        .unwrap();
        assert_eq!(
            (token.access_token.as_str(), token.expires_in),
            ("ya29.a", 3599)
        );
        let expired = refreshed(
            StatusCode::BAD_REQUEST,
            &serde_json::json!({"error":"invalid_grant","error_description":"Token has been expired or revoked."}),
        )
        .unwrap_err();
        assert!(
            expired
                .to_string()
                .starts_with("refresh credential expired or revoked")
        );
        let deleted = refreshed(
            StatusCode::UNAUTHORIZED,
            &serde_json::json!({"error":"deleted_client","error_description":"The OAuth client was deleted."}),
        )
        .unwrap_err();
        assert!(
            deleted
                .to_string()
                .contains("401 Unauthorized deleted_client: The OAuth client was deleted.")
        );
        assert!(
            refreshed(StatusCode::BAD_GATEWAY, &Value::Null)
                .unwrap_err()
                .to_string()
                .contains("502 Bad Gateway unknown_error")
        );
        assert!(
            refreshed(
                StatusCode::OK,
                &serde_json::json!({"access_token":"bad token"})
            )
            .is_err()
        );
    }
    #[test]
    fn only_google_token_replies_count() {
        assert!(from_google(&serde_json::json!({"access_token":"ya29.a"})));
        assert!(from_google(&serde_json::json!({"error":"invalid_client"})));
        assert!(!from_google(&serde_json::json!({"error":{"code":404}})));
        assert!(!from_google(&Value::Null));
    }
    #[test]
    fn pkce_rfc7636_vector() {
        assert_eq!(
            challenge("dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"),
            "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM"
        );
    }
    #[test]
    fn callback_rejects_wrong_state_and_missing_code() {
        assert!(callback("/callback?state=other&code=secret", "expected").is_err());
        assert!(callback("/callback?state=expected", "expected").is_err());
        assert_eq!(
            callback("/callback?state=expected&code=ok", "expected").unwrap(),
            Some("ok".into())
        );
        assert!(
            callback("/callback?state=expected&error=access_denied", "expected")
                .unwrap()
                .is_none()
        );
    }
    #[test]
    fn imported_credentials_cannot_redirect_tokens() {
        let credentials = Credentials::parse(br#"{"type":"authorized_user","client_id":"test","client_secret":"test","refresh_token":"test","token_uri":"https://evil.test"}"#).unwrap();
        let value = serde_json::to_value(&credentials).unwrap();
        assert!(value.get("token_uri").is_none());
        assert_eq!(value["type"], "authorized_user");
        assert!(
            Credentials::parse(
                br#"{"type":"service_account","client_id":"a","refresh_token":"b"}"#
            )
            .is_err()
        );
        assert!(
            Credentials::parse(br#"{"type":"authorized_user","client_id":"a","refresh_token":""}"#)
                .is_err()
        );
    }
}

use crate::store::Store;
use anyhow::{Context, Result, ensure};
use reqwest::blocking::Client;
use serde::{Deserialize, Serialize};
use std::{
    collections::VecDeque,
    net::{IpAddr, SocketAddr},
    path::{Path, PathBuf},
    sync::{Arc, Mutex},
    time::Duration,
};

const FIELDS: &str = "id,name,mimeType,size,modifiedTime,md5Checksum,resourceKey";
pub(crate) const API_HOST: &str = "www.googleapis.com";
pub(crate) const TOKEN_HOST: &str = "oauth2.googleapis.com";
/// TLS identity used when a censor resets the real SNI: connect and verify
/// as g.cn (a Google name this edge serves a matching certificate for) while
/// the HTTP Host header still names the real Google host.
pub(crate) const FORGED_HOST: &str = "g.cn";
/// Google issues every endpoint we touch under its own Google Trust Services
/// roots. Anchoring verification there (instead of a full CA bundle) means a
/// compromised or mis-issuing third-party CA cannot impersonate Google for
/// this client, even with a publicly leaked intermediate key.
pub(crate) const GTS_PEM: &str = include_str!("gts-roots.pem");
pub(crate) fn client_builder() -> reqwest::blocking::ClientBuilder {
    let mut builder = Client::builder().tls_built_in_root_certs(false);
    const BEGIN: &str = "-----BEGIN CERTIFICATE-----";
    const END: &str = "-----END CERTIFICATE-----";
    for block in GTS_PEM.split(BEGIN).skip(1) {
        let end = block.find(END).expect("bundled GTS root must be complete") + END.len();
        builder = builder.add_root_certificate(
            reqwest::Certificate::from_pem(format!("{BEGIN}{}", &block[..end]).as_bytes())
                .expect("bundled GTS root must parse"),
        );
    }
    builder
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct File {
    pub id: String,
    pub name: String,
    pub mime_type: String,
    pub size: Option<String>,
    pub modified_time: Option<String>,
    pub md5_checksum: Option<String>,
    pub resource_key: Option<String>,
}
impl File {
    pub fn folder(&self) -> bool {
        self.mime_type == "application/vnd.google-apps.folder"
    }
    pub fn workspace(&self) -> bool {
        self.mime_type.starts_with("application/vnd.google-apps.")
    }
    /// Binary files, or Google documents that Drive can export (as PDF in browse).
    pub fn downloadable(&self) -> bool {
        !self.workspace()
            || matches!(
                self.mime_type
                    .trim_start_matches("application/vnd.google-apps."),
                "document" | "spreadsheet" | "presentation" | "drawing"
            )
    }
}
fn client_for(ip: Option<IpAddr>, forged: Option<&str>, host: &str) -> Result<Client> {
    let mut builder = client_builder()
        .redirect(reqwest::redirect::Policy::none())
        .connect_timeout(Duration::from_secs(8))
        .timeout(Duration::from_secs(30));
    if let Some(ip) = ip {
        // Only pinned transfers bypass proxies; login verifies the account without a pin.
        builder = builder
            .no_proxy()
            .resolve(forged.unwrap_or(host), SocketAddr::new(ip, 443));
    }
    Ok(builder.build()?)
}
/// Request URL for `path` (e.g. "drive/v3/about") under the current TLS identity.
pub(crate) fn url_for(forged: Option<&str>, path: &str) -> String {
    format!("https://{}/{path}", forged.unwrap_or(API_HOST))
}
/// Rewrites a validated Google URL for the forged identity: the connection
/// and certificate name become `forged`, only the Host header stays real.
pub(crate) fn gate(forged: Option<&str>, url: &url::Url) -> url::Url {
    let mut url = url.clone();
    if let Some(host) = forged {
        let _ = url.set_host(Some(host));
    }
    url
}
/// A verified endpoint and the TLS identity stored for it (None = real name).
pub type Endpoint = (IpAddr, Option<String>);
struct Live {
    client: Client,
    ip: Option<IpAddr>,
    forged: Option<String>,
    /// Further verified endpoints (with their stored identity), fastest first.
    backups: VecDeque<Endpoint>,
}
#[derive(Clone)]
pub struct Api {
    pub db: PathBuf,
    /// The signed-in account this client acts as; None before the first login.
    pub account: Option<String>,
    /// False once the user picks --sni/--no-sni explicitly: no quiet fallback.
    auto: bool,
    live: Arc<Mutex<Live>>,
}
impl Api {
    pub fn new(
        db: PathBuf,
        account: Option<String>,
        ip: Option<IpAddr>,
        forged: Option<String>,
        auto: bool,
    ) -> Result<Self> {
        ensure!(
            forged.as_deref() != Some(""),
            "--no-sni applies to downloads; Drive API requests need an SNI name"
        );
        Ok(Self {
            live: Arc::new(Mutex::new(Live {
                client: client_for(ip, forged.as_deref(), API_HOST)?,
                ip,
                forged,
                backups: VecDeque::new(),
            })),
            db,
            account,
            auto,
        })
    }
    /// Endpoints to move to when the current one stops answering.
    pub fn with_backups(self, backups: Vec<Endpoint>) -> Self {
        self.live.lock().unwrap().backups = backups.into();
        self
    }
    /// Current endpoint, its identity and the remaining backups, for downloads.
    pub fn route(&self) -> (Option<IpAddr>, Option<String>, Vec<Endpoint>) {
        let live = self.live.lock().unwrap();
        (
            live.ip,
            live.forged.clone(),
            live.backups.iter().cloned().collect(),
        )
    }
    /// Sends one request. On a connect/timeout failure it is retried under
    /// the other TLS identity (real <-> forged g.cn), then on each backup
    /// endpoint in turn; dead endpoints are marked in SQLite. Whatever works
    /// is kept for this process and the working identity is persisted.
    pub(crate) fn deliver(
        &self,
        build: impl Fn(&Client, Option<&str>) -> reqwest::blocking::RequestBuilder,
    ) -> Result<reqwest::blocking::Response> {
        self.deliver_to(API_HOST, build)
    }
    /// `deliver` for another Google host served by the same endpoints.
    fn deliver_to(
        &self,
        host: &str,
        build: impl Fn(&Client, Option<&str>) -> reqwest::blocking::RequestBuilder,
    ) -> Result<reqwest::blocking::Response> {
        let (client, ip, forged) = {
            let live = self.live.lock().unwrap();
            let client = if host == API_HOST {
                live.client.clone()
            } else {
                client_for(live.ip, live.forged.as_deref(), host)?
            };
            (client, live.ip, live.forged.clone())
        };
        let send = |client: &Client, forged: Option<&str>| {
            build(client, forged)
                .header(reqwest::header::HOST, host)
                .send()
                .map_err(|e| e.without_url())
        };
        let transport = |e: &reqwest::Error| e.is_connect() || e.is_timeout();
        let first = match send(&client, forged.as_deref()) {
            Err(error) if ip.is_some() && transport(&error) => error,
            result => return Ok(result?),
        };
        let db = Store::open(&self.db).ok();
        let mut endpoint = ip.map(|ip| (ip, forged.clone()));
        let mut tried_current = true;
        let mut last = first;
        while let Some((ip, preferred)) = endpoint {
            // The identity already tried on the current endpoint is skipped.
            let mut identities = Vec::new();
            if !tried_current {
                identities.push(preferred.clone());
            }
            if self.auto {
                identities.push(match &preferred {
                    Some(_) => None,
                    None => Some(FORGED_HOST.to_owned()),
                });
            }
            for identity in identities {
                let client = client_for(Some(ip), identity.as_deref(), host)?;
                match send(&client, identity.as_deref()) {
                    Ok(response) => {
                        let mut live = self.live.lock().unwrap();
                        live.client = client_for(Some(ip), identity.as_deref(), API_HOST)?;
                        live.ip = Some(ip);
                        live.forged = identity.clone();
                        if let Some(db) = &db {
                            let _ = db
                                .set_sni(&ip.to_string(), identity.as_deref().unwrap_or_default());
                        }
                        return Ok(response);
                    }
                    Err(error) if transport(&error) => last = error,
                    Err(error) => return Err(error.into()),
                }
            }
            if let Some(db) = &db {
                let _ = db.endpoint(&ip.to_string(), None, Some("connection failed"), "");
            }
            tried_current = false;
            endpoint = self
                .live
                .lock()
                .unwrap()
                .backups
                .pop_front()
                .map(|(ip, stored)| {
                    // An explicit --sni applies to every endpoint.
                    (ip, if self.auto { stored } else { forged.clone() })
                });
        }
        Err(last.into())
    }
    pub fn token(&self) -> Result<String> {
        if let Ok(token) = std::env::var("GDIRECT_ACCESS_TOKEN") {
            return validate_token(token);
        }
        let db = Store::open(&self.db)?;
        if let Some(token) = self
            .account
            .as_deref()
            .map(|a| db.token(a))
            .transpose()?
            .flatten()
        {
            return Ok(token);
        }
        self.refresh()
    }
    pub fn download_token(&self) -> Result<String> {
        if let Ok(token) = std::env::var("GDIRECT_ACCESS_TOKEN") {
            return validate_token(token);
        }
        self.refresh()
    }
    fn refresh(&self) -> Result<String> {
        let db = Store::open(&self.db)?;
        // The account is verified at login; refreshing its credentials cannot change it.
        let credentials = crate::auth::credentials(&db, self.account.as_deref())?;
        let token = [REDACTED];
        if let Some(account) = &self.account {
            db.save_token(account, &token.access_token, token.expires_in)?;
        }
        Ok(token.access_token)
    }
    /// Refreshes over the pinned endpoint so transfers need no proxy for
    /// OAuth either; without one, or when it does not answer as Google's
    /// token endpoint, falls back to the system-proxy route.
    fn refresh_pinned(&self, credentials: &crate::auth::Credentials) -> Result<crate::auth::Token> {
        if self.route().0.is_some() {
            let form = credentials.refresh_form();
            let reply = self
                .deliver_to(TOKEN_HOST, |client, forged| {
                    client
                        .post(format!("https://{}/token", forged.unwrap_or(TOKEN_HOST)))
                        .form(&form)
                })
                .ok()
                .and_then(|response| {
                    let status = response.status();
                    let data = response.json().ok()?;
                    crate::auth::from_google(&data).then_some((status, data))
                });
            if let Some((status, data)) = reply {
                return crate::auth::refreshed(status, &data);
            }
        }
        crate::auth::refresh(credentials)
    }
    fn account_for_token(&self, token: &str) -> Result<String> {
        let response = self
            .deliver(|client, forged| {
                client
                    .get(url_for(forged, "drive/v3/about"))
                    .query(&[("fields", "user(emailAddress)")])
                    .bearer_auth(token)
            })
            .context(
                "cannot verify the account; check system HTTP/HTTPS proxy settings or HTTPS_PROXY and access to www.googleapis.com",
            )?;
        let data = checked(response)?;
        Ok(data["user"]["emailAddress"]
            .as_str()
            .context("Drive API did not return an account")?
            .into())
    }
    pub fn login(
        &self,
        reauth: bool,
        client: Option<&Path>,
        import: Option<&Path>,
    ) -> Result<String> {
        let db = Store::open(&self.db)?;
        let credentials =
            crate::auth::prepare_login(&db, self.account.as_deref(), client, import, reauth)?;
        let token = [REDACTED];
        // Whichever account was chosen in the browser is added (or updated) and becomes the default.
        let email = self.account_for_token(&token.access_token)?;
        db.save_account(&email, &serde_json::to_string(&credentials)?)?;
        if client.is_some() {
            db.set(
                "oauth_client",
                &serde_json::to_string(&credentials.client())?,
            )?;
        }
        db.save_token(&email, &token.access_token, token.expires_in)?;
        db.set_default_account(&email)?;
        Ok(email)
    }
    fn get(&self, path: &str, query: &[(String, String)]) -> Result<serde_json::Value> {
        self.request(reqwest::Method::GET, path, query, None)
    }
    fn request(
        &self,
        method: reqwest::Method,
        path: &str,
        query: &[(String, String)],
        body: Option<&serde_json::Value>,
    ) -> Result<serde_json::Value> {
        let build = |client: &Client, forged: Option<&str>, token: &str| {
            let mut request = client
                .request(method.clone(), url_for(forged, &format!("drive/v3/{path}")))
                .query(query)
                .bearer_auth(token);
            if let Some(body) = body {
                request = request.json(body);
            }
            request
        };
        let token = [REDACTED];
        let mut response = self.deliver(|client, forged| build(client, forged, &token))?;
        if response.status() == reqwest::StatusCode::UNAUTHORIZED
            && std::env::var_os("GDIRECT_ACCESS_TOKEN").is_none()
        {
            let token = [REDACTED];
            response = self.deliver(|client, forged| build(client, forged, &token))?;
        }
        checked(response)
    }
    /// Sends a metadata change and returns the file as Drive now reports it.
    fn write(
        &self,
        method: reqwest::Method,
        path: &str,
        extra: &[(&str, &str)],
        body: serde_json::Value,
    ) -> Result<File> {
        let mut query: Vec<(String, String)> = vec![
            ("fields".into(), FIELDS.into()),
            ("supportsAllDrives".into(), "true".into()),
        ];
        query.extend(extra.iter().map(|(k, v)| (k.to_string(), v.to_string())));
        let data = self.request(method, path, &query, Some(&body))?;
        Ok(serde_json::from_value(data)?)
    }
    /// Creates an empty file, or a folder when `folder` is set.
    pub fn create(&self, parent: &str, name: &str, folder: bool) -> Result<File> {
        ensure!(crate::drive::valid_id(parent), "invalid folder ID");
        let mut body = serde_json::json!({"name": checked_name(name)?, "parents": [parent]});
        if folder {
            body["mimeType"] = "application/vnd.google-apps.folder".into();
        }
        self.write(reqwest::Method::POST, "files", &[], body)
    }
    pub fn rename(&self, id: &str, name: &str) -> Result<File> {
        ensure!(crate::drive::valid_id(id), "invalid file ID");
        let body = serde_json::json!({"name": checked_name(name)?});
        self.write(reqwest::Method::PATCH, &format!("files/{id}"), &[], body)
    }
    /// Moves a file to the Drive trash, where it can still be restored.
    pub fn trash(&self, id: &str) -> Result<File> {
        ensure!(crate::drive::valid_id(id), "invalid file ID");
        let body = serde_json::json!({"trashed": true});
        self.write(reqwest::Method::PATCH, &format!("files/{id}"), &[], body)
    }
    /// Copies a file (not a folder; Drive cannot copy those) into `parent`, keeping its name.
    pub fn copy(&self, id: &str, parent: &str) -> Result<File> {
        ensure!(
            crate::drive::valid_id(id) && crate::drive::valid_id(parent),
            "invalid file ID"
        );
        let body = serde_json::json!({"parents": [parent]});
        self.write(
            reqwest::Method::POST,
            &format!("files/{id}/copy"),
            &[],
            body,
        )
    }
    /// Moves a file or folder out of all its current folders into `parent`.
    /// Returns false when it is already there.
    pub fn move_to(&self, id: &str, parent: &str) -> Result<bool> {
        ensure!(
            crate::drive::valid_id(id) && crate::drive::valid_id(parent),
            "invalid file ID"
        );
        let data = self.get(
            &format!("files/{id}"),
            &[
                ("fields".into(), "parents".into()),
                ("supportsAllDrives".into(), "true".into()),
            ],
        )?;
        let parents: Vec<String> = serde_json::from_value(data["parents"].clone())?;
        // "root" is an alias; Drive reports the real ID, so compare after resolving it.
        let target = if parent == "root" {
            self.metadata("root")?.id
        } else {
            parent.to_owned()
        };
        if parents == [target.as_str()] {
            return Ok(false);
        }
        let remove = parents
            .iter()
            .filter(|p| **p != target)
            .cloned()
            .collect::<Vec<_>>()
            .join(",");
        self.write(
            reqwest::Method::PATCH,
            &format!("files/{id}"),
            &[("addParents", &target), ("removeParents", &remove)],
            serde_json::json!({}),
        )?;
        Ok(true)
    }
    pub fn list(&self, folder: &str) -> Result<Vec<File>> {
        ensure!(crate::drive::valid_id(folder), "invalid folder ID");
        let mut files = Vec::new();
        let mut page = String::new();
        loop {
            let mut query=vec![("q".into(),format!("'{folder}' in parents and trashed = false")),
                ("fields".into(),"nextPageToken,files(id,name,mimeType,size,modifiedTime,md5Checksum,resourceKey)".into()),
                ("pageSize".into(),"1000".into()),("orderBy".into(),"folder,name_natural".into()),
                ("supportsAllDrives".into(),"true".into()),("includeItemsFromAllDrives".into(),"true".into())];
            if !page.is_empty() {
                query.push(("pageToken".into(), page));
            }
            let data = self.get("files", &query)?;
            files.extend(serde_json::from_value::<Vec<File>>(data["files"].clone())?);
            page = data["nextPageToken"]
                .as_str()
                .unwrap_or_default()
                .to_owned();
            if page.is_empty() {
                break;
            }
        }
        Store::open(&self.db)?.cache(
            self.account.as_deref().unwrap_or_default(),
            folder,
            &serde_json::to_string(&files)?,
        )?;
        Ok(files)
    }
    pub fn metadata(&self, id: &str) -> Result<File> {
        let id = crate::drive::FileRef::parse(id)?.id;
        let data = self.get(
            &format!("files/{id}"),
            &[
                ("fields".into(), FIELDS.into()),
                ("supportsAllDrives".into(), "true".into()),
            ],
        )?;
        Ok(serde_json::from_value(data)?)
    }
    pub fn cached(&self, folder: &str) -> Result<Vec<File>> {
        Store::open(&self.db)?
            .cached(self.account.as_deref().unwrap_or_default(), folder)?
            .map(|json| serde_json::from_str(&json).map_err(Into::into))
            .unwrap_or_else(|| Ok(Vec::new()))
    }
}
pub fn validate_token(token: String) -> Result<String> {
    ensure!(
        !token.is_empty() && token.bytes().all(|b| b.is_ascii_graphic()),
        "invalid access token"
    );
    Ok(token)
}
fn checked(response: reqwest::blocking::Response) -> Result<serde_json::Value> {
    let status = response.status();
    let body = response.text().map_err(|e| e.without_url())?;
    if status.is_success() {
        return serde_json::from_str(&body).context("Drive API returned invalid JSON");
    }
    anyhow::bail!("{}", drive_error(status, &body))
}
fn drive_error(status: reqwest::StatusCode, body: &str) -> String {
    let data: serde_json::Value = serde_json::from_str(body).unwrap_or_default();
    let message = data["error"]["message"]
        .as_str()
        .unwrap_or("request failed");
    // Missing scope or a disabled Drive API; per-file permission errors use other reasons.
    let text = data.to_string();
    if status == reqwest::StatusCode::FORBIDDEN
        && [
            "insufficientPermissions",
            "ACCESS_TOKEN_SCOPE_INSUFFICIENT",
            "accessNotConfigured",
            "SERVICE_DISABLED",
        ]
        .iter()
        .any(|reason| text.contains(reason))
    {
        return format!(
            "Drive API {status}: insufficient permission ({message}). Enable the Drive API in the OAuth client's project, then run gdirect login --reauth and allow Drive access"
        );
    }
    format!("Drive API {status}: {message}")
}
fn checked_name(name: &str) -> Result<&str> {
    let name = name.trim();
    ensure!(!name.is_empty(), "name cannot be empty");
    ensure!(
        !name.chars().any(char::is_control),
        "name cannot contain control characters"
    );
    Ok(name)
}
pub fn safe_name(name: &str) -> String {
    let cleaned: String = name
        .chars()
        .map(|c| {
            if c == '/' || c == '\\' || c.is_control() {
                '_'
            } else {
                c
            }
        })
        .collect();
    if cleaned.is_empty() || cleaned == "." || cleaned == ".." {
        "download".into()
    } else {
        cleaned
    }
}
pub fn destination(dir: &Path, file: &File) -> PathBuf {
    dir.join(safe_name(&file.name))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn login_client_uses_proxy() {
        crate::test_network::assert_route("api::tests::login_client_uses_proxy", true, |url| {
            Ok(client_for(None, None, API_HOST)?
                .get(url)
                .send()?
                .error_for_status()?
                .json()?)
        });
    }
    #[test]
    fn pinned_client_bypasses_proxy() {
        crate::test_network::assert_route(
            "api::tests::pinned_client_bypasses_proxy",
            false,
            |url| {
                Ok(client_for(Some("127.0.0.1".parse()?), None, API_HOST)?
                    .get(url)
                    .send()?
                    .error_for_status()?
                    .json()?)
            },
        );
    }
    #[test]
    fn urls_keep_drive_and_upload_paths() {
        assert_eq!(
            url_for(None, "drive/v3/about"),
            "https://www.googleapis.com/drive/v3/about"
        );
        assert_eq!(
            url_for(None, "upload/drive/v3/files"),
            "https://www.googleapis.com/upload/drive/v3/files"
        );
        assert_eq!(
            url_for(Some(FORGED_HOST), "upload/drive/v3/files"),
            "https://g.cn/upload/drive/v3/files"
        );
    }
    #[test]
    fn drive_errors_keep_status_and_hint_only_for_scope() {
        use reqwest::StatusCode;
        assert_eq!(
            drive_error(StatusCode::BAD_GATEWAY, "<html>bad gateway</html>"),
            "Drive API 502 Bad Gateway: request failed"
        );
        assert_eq!(
            drive_error(
                StatusCode::NOT_FOUND,
                r#"{"error":{"message":"File not found: x."}}"#
            ),
            "Drive API 404 Not Found: File not found: x."
        );
        let scope = drive_error(
            StatusCode::FORBIDDEN,
            r#"{"error":{"message":"Request had insufficient authentication scopes.","errors":[{"reason":"insufficientPermissions"}]}}"#,
        );
        assert!(scope.starts_with("Drive API 403 Forbidden: insufficient permission"));
        assert!(scope.contains("gdirect login --reauth"));
        let file = drive_error(
            StatusCode::FORBIDDEN,
            r#"{"error":{"message":"No access.","errors":[{"reason":"insufficientFilePermissions"}]}}"#,
        );
        assert_eq!(file, "Drive API 403 Forbidden: No access.");
    }
    #[test]
    fn only_binary_and_exportable_items_download() {
        let file = |mime: &str| File {
            id: "x".into(),
            name: "x".into(),
            mime_type: mime.into(),
            size: None,
            modified_time: None,
            md5_checksum: None,
            resource_key: None,
        };
        assert!(file("application/zip").downloadable());
        assert!(file("application/vnd.google-apps.document").downloadable());
        assert!(!file("application/vnd.google-apps.shortcut").downloadable());
        assert!(!file("application/vnd.google-apps.form").downloadable());
    }
    #[test]
    fn names_cannot_escape() {
        assert_eq!(safe_name("../a\n"), ".._a_");
        assert_eq!(safe_name(".."), "download");
    }
}

#!/usr/bin/env python3
"""Offline TLS/range integration tests against the actual patched libaria2."""
import hashlib
import http.server
import os
from pathlib import Path
import signal
import ssl
import subprocess
import sys
import tempfile
import threading
import time

ROOT = Path(__file__).resolve().parents[1]
DATA = bytes(range(256)) * 32768
requests = []
snis = []

class Handler(http.server.BaseHTTPRequestHandler):
    def log_message(self, *_):
        pass

    def do_GET(self):
        requests.append((self.path, self.headers.get('Range'), self.headers.get('Authorization'), self.headers.get('Host')))
        if self.path == '/redirect':
            self.send_response(302)
            self.send_header('Location', 'https://example.com/steal')
            self.send_header('Content-Length', '0')
            self.end_headers()
            return
        if self.path == '/media':
            self.send_response(302)
            self.send_header('Location', f'https://drive.usercontent.google.com:{self.server.server_port}/blob')
            self.send_header('Content-Length', '0')
            self.end_headers()
            return
        start, end = 0, len(DATA)-1
        if self.headers.get('Range'):
            left, right = self.headers['Range'].removeprefix('bytes=').split('-')
            start, end = int(left), int(right) if right else end
            end = min(end, len(DATA)-1)
            self.send_response(206)
            self.send_header('Content-Range', f'bytes {start}-{end}/{len(DATA)}')
        else:
            self.send_response(200)
        self.send_header('Accept-Ranges', 'bytes')
        self.send_header('Content-Type', 'application/octet-stream')
        self.send_header('Content-Length', str(end-start+1))
        self.end_headers()
        try:
            for i in range(start, end+1, 65536):
                self.wfile.write(DATA[i:min(i+65536,end+1)])
                self.wfile.flush()
                if self.path == '/slow':
                    time.sleep(.025)
        except (BrokenPipeError, ConnectionResetError, ssl.SSLError):
            pass

def main():
    with tempfile.TemporaryDirectory(prefix='gdirect-test-') as tmp:
        tmp = Path(tmp)
        # Portable releases must work without the build machine's OpenSSL modules.
        os.environ['OPENSSL_MODULES'] = str(tmp / 'no-openssl-modules')
        ssl_prefix = os.environ.get('OPENSSL_PREFIX')
        if sys.platform == 'darwin' and not ssl_prefix:
            ssl_prefix = subprocess.check_output(['brew','--prefix','openssl@3'],text=True).strip()
        harness = tmp/'main.cc'
        harness.write_text('''#include <cstdint>
#include <cstdlib>
#include <cstdio>
#include <string>
#include <thread>
extern "C" int gdirect_download(const char*,const char*,const char*,const char*,const char*,const char*,const char*,int) noexcept;
using Callback=int(*)(int64_t,int64_t,int,int,void*);
extern "C" int gdirect_download_ex(const char*,const char*,const char*,const char*,const char*,const char*,const char*,int,Callback,void*,bool) noexcept;
int progress(int64_t done,int64_t total,int speed,int connections,void* data){
  ++*static_cast<int*>(data);return std::getenv("GDIRECT_TEST_CANCEL") && done>0;
}
int main(int n,char**v){
 if(n!=8)return 99;
 if(std::getenv("GDIRECT_TEST_REPEAT")){
  // browse runs one download after another, each on a fresh worker thread.
  for(int i=0;i<3;i++){
   std::string name=std::string(v[3])+"."+std::to_string(i);int result=99,count=0;
   std::thread worker([&]{result=gdirect_download_ex(v[1],v[2],name.c_str(),"127.0.0.1",v[4],v[5],v[6],v[7][0]-'0',progress,&count,false);});
   worker.join();if(result)return result;
  }
  return 0;
 }
 if(!std::getenv("GDIRECT_TEST_CALLBACK"))return gdirect_download(v[1],v[2],v[3],"127.0.0.1",v[4],v[5],v[6],v[7][0]-'0');
 int result=99,count=0;
 std::thread worker([&]{result=gdirect_download_ex(v[1],v[2],v[3],"127.0.0.1",v[4],v[5],v[6],v[7][0]-'0',progress,&count,false);});
 worker.join();std::printf("callbacks=%d\\n",count);return count>0 ? result : 98;
}
''')
        cmd = ['c++','-std=c++11',str(harness),str(ROOT/'native/bridge.cc'),'-I'+str(ROOT/'target/libaria2/include'),str(ROOT/'target/libaria2/lib/libaria2.a')]
        if ssl_prefix:
            cmd += ['-L'+ssl_prefix+'/lib']
        if sys.platform == 'darwin':
            cmd += ['-framework','Security']
        cmd += ['-pthread','-lssl','-lcrypto']
        if sys.platform == 'win32':
            cmd += ['-lws2_32','-lwsock32','-lgdi32','-lwinmm','-liphlpapi','-lpsapi','-lcrypt32','-lbcrypt','-ladvapi32']
        cmd += ['-o',str(tmp/'harness')]
        subprocess.run(cmd,check=True)
        # The certificate covers both the real hosts and the forged identity:
        # in forged mode gdirect connects and verifies as g.cn while Host: keeps
        # the real hostname, so the fixture must certify all of them.
        subprocess.run(['openssl','req','-x509','-newkey','rsa:2048','-nodes','-days','1','-subj','/CN=drive.usercontent.google.com','-addext','subjectAltName=DNS:drive.usercontent.google.com,DNS:www.googleapis.com,DNS:g.cn','-keyout',str(tmp/'key.pem'),'-out',str(tmp/'cert.pem')],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        server = http.server.ThreadingHTTPServer(('127.0.0.1',0), Handler)
        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(tmp/'cert.pem',tmp/'key.pem')
        context.set_servername_callback(lambda sock,name,ctx:snis.append(name))
        server.socket = context.wrap_socket(server.socket,server_side=True)
        threading.Thread(target=server.serve_forever,daemon=True).start()
        def command(name,path='/blob',host='drive.usercontent.google.com',sni='g.cn',token='',ca=None):
            return [str(tmp/'harness'),f'https://{host}:{server.server_port}{path}',str(tmp),name,sni,token,str(ca or tmp/'cert.pem'),'4']
        def run(*args,success=True,**kwargs):
            p=subprocess.run(command(*args,**kwargs),capture_output=True,text=True,timeout=30)
            assert (p.returncode == 0) == success, (p.returncode,p.stdout,p.stderr)
        def check(name):
            assert hashlib.sha256((tmp/name).read_bytes()).digest()==hashlib.sha256(DATA).digest()
        try:
            run('split.bin'); check('split.bin')
            assert 'g.cn' in snis and any(r[1] for r in requests)
            assert all(r[3] == 'drive.usercontent.google.com' for r in requests)
            print('PASS: pinned IP, forged SNI identity, real Host header, parallel ranges and byte integrity')
            run('no-sni.bin',sni='');check('no-sni.bin');assert None in snis
            print('PASS: no-SNI with certificate verification')
            # With no forged identity the certificate is checked against the
            # URL's own hostname; the fixture cert does not cover drive.google.com.
            run('mismatch.bin',host='drive.google.com',sni='',success=False)
            print('PASS: rejects wrong original hostname despite successful TLS transport')
            run('redirect.bin',path='/redirect',success=False)
            print('PASS: rejects non-Google redirects')
            requests.clear()
            run('media.bin',path='/media',host='www.googleapis.com',token='[REDACTED]');check('media.bin')
            assert any(p=='/media' and t=='Bearer fixture-token' for p,_,t,_ in requests)
            assert all(t is None for p,_,t,_ in requests if p=='/blob')
            assert all(h == 'drive.usercontent.google.com' for p,_,_,h in requests if p == '/blob')
            print('PASS: OAuth token is stripped from media redirects')
            if sys.platform != 'win32':
                p=subprocess.Popen(command('resume.bin',path='/slow'),stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
                time.sleep(.4);p.send_signal(signal.SIGINT);p.wait(timeout=15)
                assert (tmp/'resume.bin.aria2').exists(), 'missing resume control file'
                requests.clear()
                run('resume.bin',path='/slow');check('resume.bin')
                assert any(r[1] and r[1] != 'bytes=0-' for r in requests)
                assert not (tmp/'resume.bin.aria2').exists()
                print('PASS: interrupted download resumes with complete byte integrity')
            env=dict(os.environ, GDIRECT_TEST_CALLBACK='1')
            p=subprocess.run(command('callback.bin',path='/slow'),env=env,capture_output=True,text=True,timeout=30)
            assert p.returncode==0 and 'callbacks=' in p.stdout, (p.returncode,p.stdout,p.stderr)
            check('callback.bin')
            p=subprocess.run(command('cancel.bin',path='/slow'),env=dict(env,GDIRECT_TEST_CANCEL='1'),capture_output=True,text=True,timeout=30)
            assert p.returncode not in (0,98) and (tmp/'cancel.bin.aria2').exists(), (p.returncode,p.stdout,p.stderr)
            run('cancel.bin',path='/slow');check('cancel.bin')
            print('PASS: worker-thread progress callback, cancellation and resume')
            p=subprocess.run(command('repeat.bin'),env=dict(os.environ,GDIRECT_TEST_REPEAT='1'),capture_output=True,text=True,timeout=60)
            assert p.returncode==0, (p.returncode,p.stdout,p.stderr)
            for i in range(3):
                check(f'repeat.bin.{i}')
            print('PASS: several downloads in one process')
        finally:
            server.shutdown();server.server_close()

if __name__ == '__main__':
    main()

//! Exercise real HTTP routing in child processes so proxy variables cannot affect other tests.
use anyhow::Result;
use serde_json::Value;
use std::{
    io::{BufRead, BufReader, Read, Write},
    net::TcpListener,
    process::Command,
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    thread,
    time::{Duration, Instant},
};

fn serve(
    listener: TcpListener,
    route: &str,
    stop: Arc<AtomicBool>,
) -> thread::JoinHandle<Option<String>> {
    let body = serde_json::json!({"route": route}).to_string();
    listener.set_nonblocking(true).unwrap();
    thread::spawn(move || {
        let deadline = Instant::now() + Duration::from_secs(50);
        while !stop.load(Ordering::Relaxed) && Instant::now() < deadline {
            match listener.accept() {
                Ok((mut stream, _)) => {
                    stream
                        .set_read_timeout(Some(Duration::from_secs(3)))
                        .unwrap();
                    let mut reader = BufReader::new(stream.try_clone().unwrap());
                    let mut first = String::new();
                    reader.read_line(&mut first).unwrap();
                    let mut line = String::new();
                    let mut length = 0;
                    loop {
                        line.clear();
                        let bytes = reader.read_line(&mut line).unwrap();
                        if bytes == 0 || line == "\r\n" {
                            break;
                        }
                        if let Some((name, value)) = line.split_once(':')
                            && name.eq_ignore_ascii_case("content-length")
                        {
                            length = value.trim().parse::<usize>().unwrap();
                        }
                    }
                    assert!(length < 8192, "unexpected fixture body size");
                    reader.read_exact(&mut vec![0; length]).unwrap();
                    let status = if first.starts_with("CONNECT ") {
                        "502 Bad Gateway"
                    } else {
                        "200 OK"
                    };
                    write!(
                        stream,
                        "HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                        body.len()
                    )
                    .unwrap();
                    return Some(first);
                }
                Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                    thread::sleep(Duration::from_millis(10));
                }
                Err(error) => panic!("fixture accept failed: {error}"),
            }
        }
        None
    })
}

pub fn assert_route(test: &str, proxied: bool, request: impl FnOnce(&str) -> Result<Value>) {
    if std::env::var("GDIRECT_TEST_NETWORK").as_deref() == Ok(test) {
        let url = std::env::var("GDIRECT_TEST_URL").unwrap();
        if url.starts_with("https:") {
            // The proxy rejects CONNECT before TLS, without changing certificate verification.
            assert!(request(&url).is_err());
        } else {
            let data = request(&url).unwrap();
            assert_eq!(data["route"], if proxied { "proxy" } else { "direct" });
        }
        return;
    }

    run_fixture(test, proxied, "http");
    if proxied {
        run_fixture(test, proxied, "https");
    }
}

fn run_fixture(test: &str, proxied: bool, scheme: &str) {
    let proxy = TcpListener::bind("127.0.0.1:0").unwrap();
    let origin = TcpListener::bind("127.0.0.1:0").unwrap();
    let proxy_url = format!("http://{}", proxy.local_addr().unwrap());
    let host = if proxied {
        "proxy-route.invalid"
    } else {
        "www.googleapis.com"
    };
    let url = format!(
        "{scheme}://{host}:{}/fixture",
        origin.local_addr().unwrap().port()
    );
    let stop = Arc::new(AtomicBool::new(false));
    let proxy_thread = serve(proxy, "proxy", stop.clone());
    let origin_thread = serve(origin, "direct", stop.clone());
    let mut command = Command::new(std::env::current_exe().unwrap());
    command
        .args(["--exact", test, "--nocapture"])
        .env("GDIRECT_TEST_NETWORK", test)
        .env("GDIRECT_TEST_URL", url)
        .env_remove("REQUEST_METHOD");
    for name in [
        "HTTP_PROXY",
        "http_proxy",
        "HTTPS_PROXY",
        "https_proxy",
        "ALL_PROXY",
        "all_proxy",
    ] {
        command.env(name, &proxy_url);
    }
    command.env("NO_PROXY", "").env("no_proxy", "");
    let output = command.output();
    stop.store(true, Ordering::Relaxed);
    let proxy_used = proxy_thread.join().unwrap();
    let origin_used = origin_thread.join().unwrap();
    let output = output.unwrap();
    assert!(
        output.status.success(),
        "routing subprocess failed:\n{}\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        (proxy_used.is_some(), origin_used.is_some()),
        (proxied, !proxied)
    );
    if scheme == "https" {
        assert!(
            proxy_used
                .unwrap()
                .starts_with("CONNECT proxy-route.invalid:")
        );
    }
}

param(
    [string]$Version,
    [string]$InstallDir = "$env:LOCALAPPDATA\gdirect\bin",
    [string]$ArtifactDir,
    [switch]$WithMount,
    [switch]$NoPath
)
$ErrorActionPreference = 'Stop'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
if (-not [Environment]::Is64BitOperatingSystem -or $env:PROCESSOR_ARCHITECTURE -eq 'ARM64') {
    throw 'The Windows release requires an x86_64 PC.'
}
if (-not $Version) {
    $Version = (Invoke-RestMethod 'https://api.github.com/repos/mizorewww/gdirect/releases/latest').tag_name -replace '^v', ''
}
if ($Version -notmatch '^\d+\.\d+\.\d+$') { throw 'Invalid release version.' }
$Name = "gdirect-$Version-x86_64-pc-windows-gnu.zip"
$TempDir = Join-Path ([IO.Path]::GetTempPath()) ([Guid]::NewGuid().ToString())
New-Item -ItemType Directory $TempDir | Out-Null
try {
    if ($ArtifactDir) {
        Copy-Item (Join-Path $ArtifactDir $Name) $TempDir
        Copy-Item (Join-Path $ArtifactDir 'SHA256SUMS') $TempDir
    } else {
        $Base = "https://github.com/mizorewww/gdirect/releases/download/v$Version"
        Invoke-WebRequest "$Base/$Name" -OutFile (Join-Path $TempDir $Name) -UseBasicParsing
        Invoke-WebRequest "$Base/SHA256SUMS" -OutFile (Join-Path $TempDir 'SHA256SUMS') -UseBasicParsing
    }
    $Expected = $null
    foreach ($Line in (Get-Content (Join-Path $TempDir 'SHA256SUMS'))) {
        if ($Line.Trim() -match ('^([0-9a-fA-F]{64})\s+\*?' + [regex]::Escape($Name) + '$')) { $Expected = $Matches[1] }
    }
    $Actual = (Get-FileHash (Join-Path $TempDir $Name) -Algorithm SHA256).Hash
    if (-not $Expected -or $Expected -ne $Actual) { throw 'Release checksum verification failed.' }
    Expand-Archive (Join-Path $TempDir $Name) (Join-Path $TempDir 'extracted')
    $Root = Join-Path $TempDir "extracted\gdirect-$Version-x86_64-pc-windows-gnu"
    New-Item -ItemType Directory -Force $InstallDir | Out-Null
    Copy-Item "$Root\*" $InstallDir -Recurse -Force
    if ($WithMount) {
        $Rclone = Get-Command rclone -ErrorAction SilentlyContinue
        $NeedsRclone = -not $Rclone
        if ($Rclone) {
            $Line = (& $Rclone.Source version | Select-Object -First 1)
            if ($Line -match '^rclone v(\d+\.\d+\.\d+)') { $NeedsRclone = [version]$Matches[1] -lt [version]'1.75.2' }
            else { $NeedsRclone = $true }
        }
        $HasWinFsp = (Test-Path 'HKLM:\SOFTWARE\WinFsp') -or (Test-Path 'HKLM:\SOFTWARE\WOW6432Node\WinFsp')
        if (($NeedsRclone -or -not $HasWinFsp) -and -not (Get-Command winget -ErrorAction SilentlyContinue)) {
            throw 'Mount dependencies need winget. Install/update Microsoft App Installer, then rerun with -WithMount.'
        }
        $Packages = @()
        if ($NeedsRclone) { $Packages += 'Rclone.Rclone' }
        if (-not $HasWinFsp) { $Packages += 'WinFsp.WinFsp' }
        foreach ($Package in $Packages) {
            & winget install --id $Package --exact --accept-package-agreements --accept-source-agreements
            if ($LASTEXITCODE -ne 0 -and $LASTEXITCODE -ne 3010) { throw "Failed to install $Package ($LASTEXITCODE)." }
        }
    }
    if (-not $NoPath) {
        $UserPath = [Environment]::GetEnvironmentVariable('Path', 'User')
        if (($UserPath -split ';') -notcontains $InstallDir) {
            [Environment]::SetEnvironmentVariable('Path', "$InstallDir;$UserPath", 'User')
        }
        $env:Path = "$InstallDir;$env:Path"
    }
    & (Join-Path $InstallDir 'gdirect.exe') --version
    if ($LASTEXITCODE -ne 0) { throw 'Installed executable failed its smoke test.' }
    Write-Host "Installed in $InstallDir. Open a new terminal to refresh PATH."
    Write-Host 'Next: create a Google OAuth client (one time), then sign in:'
    Write-Host '  https://github.com/mizorewww/gdirect/blob/main/docs/configuration/README.md'
    Write-Host '  gdirect login --client-secret C:\path\to\client_secret.json'
} finally {
    Remove-Item $TempDir -Recurse -Force
}

use std::{env, path::PathBuf, process::Command};
fn main() {
    let root = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").unwrap());
    let prefix = root.join("target/libaria2");
    let os = env::var("CARGO_CFG_TARGET_OS").unwrap();
    let static_ssl = env::var("OPENSSL_STATIC").as_deref() == Ok("1");
    assert!(
        prefix.join("lib/libaria2.a").exists(),
        "Run ./scripts/build-libaria2.sh first (pinned aria2 1.37.0)"
    );
    let mut bridge = cc::Build::new();
    bridge
        .cpp(true)
        .std("c++11")
        .file("native/bridge.cc")
        .include(prefix.join("include"));
    if os == "windows" {
        assert_eq!(
            env::var("CARGO_CFG_TARGET_ENV").unwrap(),
            "gnu",
            "Windows builds use the MinGW GNU toolchain"
        );
        // Emit the C++ runtime after libaria2: GNU archives are searched left to right.
        bridge.cpp_link_stdlib(None);
        let output = Command::new("g++")
            .arg("-print-file-name=libstdc++.a")
            .output()
            .expect("MinGW g++ required");
        let library = PathBuf::from(String::from_utf8(output.stdout).unwrap().trim());
        if let Some(parent) = library.parent() {
            println!("cargo:rustc-link-search=native={}", parent.display());
        }
    }
    bridge.compile("gdirect_bridge");
    println!(
        "cargo:rustc-link-search=native={}",
        prefix.join("lib").display()
    );
    println!("cargo:rustc-link-lib=static=aria2");
    if os == "windows" {
        println!("cargo:rustc-link-lib=static=stdc++");
    }
    let ssl = env::var("OPENSSL_PREFIX").ok().or_else(|| {
        (os == "macos").then(|| {
            let out = Command::new("brew")
                .args(["--prefix", "openssl@3"])
                .output()
                .expect("brew or OPENSSL_PREFIX required");
            assert!(out.status.success());
            String::from_utf8(out.stdout).unwrap().trim().into()
        })
    });
    if let Some(ssl) = &ssl {
        println!("cargo:rustc-link-search=native={ssl}/lib");
    }
    if static_ssl && os == "macos" {
        // Darwin's -l search can prefer a dylib even for Rust static native libraries.
        let ssl = ssl
            .as_ref()
            .expect("OPENSSL_PREFIX is required for macOS release builds");
        println!("cargo:rustc-link-arg={ssl}/lib/libssl.a");
        println!("cargo:rustc-link-arg={ssl}/lib/libcrypto.a");
    } else {
        let linkage = if static_ssl { "static=" } else { "" };
        println!("cargo:rustc-link-lib={linkage}ssl");
        println!("cargo:rustc-link-lib={linkage}crypto");
    }
    match os.as_str() {
        "macos" => println!("cargo:rustc-link-lib=framework=Security"),
        "windows" => {
            for lib in [
                "ws2_32", "wsock32", "gdi32", "winmm", "iphlpapi", "psapi", "crypt32", "bcrypt",
                "advapi32",
            ] {
                println!("cargo:rustc-link-lib={lib}");
            }
            println!("cargo:rustc-link-arg=-static");
        }
        "linux" if static_ssl => {
            println!("cargo:rustc-link-lib=dl");
            println!("cargo:rustc-link-lib=pthread");
        }
        _ => {}
    }
    for path in [
        "native/bridge.cc",
        "vendor/gdirect_route.h",
        "target/libaria2/lib/libaria2.a",
    ] {
        println!("cargo:rerun-if-changed={path}");
    }
    for var in ["OPENSSL_PREFIX", "OPENSSL_STATIC"] {
        println!("cargo:rerun-if-env-changed={var}");
    }
}

use crate::download::allowed_url;
use anyhow::{Context, Result, ensure};
use scraper::{Html, Selector};
use url::Url;

#[derive(Debug, PartialEq)]
pub struct FileRef {
    pub id: String,
    pub resource_key: Option<String>,
}
pub fn valid_id(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 256
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}
impl FileRef {
    pub fn parse(input: &str) -> Result<Self> {
        if valid_id(input) {
            return Ok(Self {
                id: input.into(),
                resource_key: None,
            });
        }
        let url = Url::parse(input).context("expected a Drive file ID or sharing URL")?;
        ensure!(
            allowed_url(&url),
            "expected a Google Drive HTTPS sharing URL"
        );
        let parts: Vec<_> = url.path_segments().into_iter().flatten().collect();
        let id = parts
            .windows(2)
            .find(|p| p[0] == "d")
            .map(|p| p[1].to_owned())
            .or_else(|| {
                url.query_pairs()
                    .find(|(k, _)| k == "id")
                    .map(|(_, v)| v.into_owned())
            })
            .context("no file ID in URL (folders are not supported)")?;
        ensure!(valid_id(&id), "invalid Drive file ID");
        let resource_key = url
            .query_pairs()
            .find(|(k, _)| k == "resourcekey")
            .map(|(_, v)| v.into_owned());
        if let Some(key) = &resource_key {
            ensure!(valid_id(key), "invalid resource key");
        }
        Ok(Self { id, resource_key })
    }
    pub fn url(&self, authenticated: bool, export: Option<&str>) -> Result<Url> {
        ensure!(
            export.is_none() || authenticated,
            "--export requires gdirect login or GDIRECT_ACCESS_TOKEN"
        );
        let mut url = if authenticated {
            Url::parse(&format!(
                "https://www.googleapis.com/drive/v3/files/{}{}",
                self.id,
                if export.is_some() { "/export" } else { "" }
            ))?
        } else {
            Url::parse("https://drive.usercontent.google.com/download")?
        };
        {
            let mut q = url.query_pairs_mut();
            if authenticated {
                if let Some(mime) = export {
                    q.append_pair("mimeType", mime);
                } else {
                    q.append_pair("alt", "media")
                        .append_pair("supportsAllDrives", "true");
                }
            } else {
                q.append_pair("id", &self.id)
                    .append_pair("export", "download")
                    .append_pair("confirm", "t");
            }
            if let Some(key) = &self.resource_key {
                q.append_pair("resourcekey", key);
            }
        }
        Ok(url)
    }
}

pub fn confirmation(html: &str, base: &Url) -> Result<Url> {
    let document = Html::parse_document(html);
    let form_selector = Selector::parse("form#download-form").unwrap();
    let input_selector = Selector::parse("input[name]").unwrap();
    let form = document.select(&form_selector).next().context("Drive returned an HTML page instead of a file; check sharing permissions, quota or authentication")?;
    ensure!(
        form.value()
            .attr("method")
            .unwrap_or("get")
            .eq_ignore_ascii_case("get"),
        "unsupported confirmation method"
    );
    let mut target = base.join(
        form.value()
            .attr("action")
            .context("confirmation form has no action")?,
    )?;
    ensure!(
        allowed_url(&target),
        "untrusted confirmation form destination"
    );
    for input in form.select(&input_selector) {
        target.query_pairs_mut().append_pair(
            input.value().attr("name").unwrap(),
            input.value().attr("value").unwrap_or(""),
        );
    }
    Ok(target)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn links() {
        assert_eq!(
            FileRef::parse("https://drive.google.com/file/d/abc_123/view?resourcekey=key-1")
                .unwrap(),
            FileRef {
                id: "abc_123".into(),
                resource_key: Some("key-1".into())
            }
        );
        assert_eq!(
            FileRef::parse("https://drive.google.com/open?id=abc")
                .unwrap()
                .id,
            "abc"
        );
        assert!(FileRef::parse("https://evil.test/file/d/abc").is_err());
        assert!(FileRef::parse("https://drive.google.com/drive/folders/abc").is_err());
        assert!(FileRef::parse("a/b").is_err());
    }
    #[test]
    fn confirm_form() {
        let base = Url::parse("https://drive.usercontent.google.com/download").unwrap();
        let u = confirmation(r#"<form id="download-form" action="/download"><input name="uuid" value="a&amp;b"><input name="confirm" value="t"></form>"#, &base).unwrap();
        assert!(u.query_pairs().any(|(k, v)| k == "uuid" && v == "a&b"));
        assert!(
            confirmation(
                r#"<form id="download-form" action="https://evil.test/"></form>"#,
                &base
            )
            .is_err()
        );
        assert!(confirmation("<html>quota exceeded</html>", &base).is_err());
    }
}

use crate::{api::Api, store::Store};
use anyhow::{Context, Result, ensure};
use serde::{Deserialize, Serialize};
use std::{
    fs,
    path::{Path, PathBuf},
    process::{Command, Stdio},
    time::Duration,
};

#[derive(Serialize, Deserialize)]
struct Mounted {
    path: PathBuf,
    pid: u32,
    config: PathBuf,
}
fn default_mount() -> Result<PathBuf> {
    Ok(dirs::home_dir()
        .context("cannot locate home directory")?
        .join("GoogleDrive"))
}
pub fn run(
    api: &Api,
    path: Option<&Path>,
    read_only: bool,
    foreground: bool,
    connections: u8,
) -> Result<()> {
    let version = Command::new("rclone")
        .arg("version")
        .output()
        .context("install rclone first (macOS: brew install rclone)")?;
    ensure!(version.status.success(), "rclone is unavailable");
    let version_text = String::from_utf8_lossy(&version.stdout);
    let number = version_text
        .lines()
        .next()
        .unwrap_or("")
        .strip_prefix("rclone v")
        .unwrap_or("");
    let parts: Vec<u32> = number
        .split('.')
        .take(3)
        .map(|part| {
            part.chars()
                .take_while(|c| c.is_ascii_digit())
                .collect::<String>()
                .parse()
                .unwrap_or(0)
        })
        .collect();
    ensure!(
        parts.len() == 3 && (parts[0], parts[1], parts[2]) >= (1, 75, 2),
        "rclone 1.75.2+ is required for mounting; update it using the installer or brew upgrade rclone"
    );
    if cfg!(target_os = "linux") {
        let fuse = Command::new("fusermount3")
            .arg("--version")
            .output()
            .context(
                "mounting requires FUSE3 (fusermount3); run the installer with --with-mount",
            )?;
        ensure!(fuse.status.success(), "fusermount3 is unavailable");
    }

    let db = Store::open(&api.db)?;
    let account = api.account.clone().context("run gdirect login first")?;
    let key = Store::mount_key(&account);
    ensure!(
        db.setting(&key)?.is_none(),
        "{account} is already mounted; run gdirect unmount --account {account} first"
    );
    let credentials_data = crate::auth::credentials(&db, Some(&account))?;
    // Fail here rather than inside rclone if the saved login no longer works.
    crate::auth::refresh(&credentials_data)?;
    let email = account.as_str();
    let path = path
        .map(Path::to_path_buf)
        .map(Ok)
        .unwrap_or_else(default_mount)?;
    #[cfg(windows)]
    let path = {
        ensure!(
            !path.exists(),
            "Windows mount directory must not already exist"
        );
        let absolute = std::path::absolute(&path)?;
        let parent = absolute
            .parent()
            .context("mount requires a directory path")?;
        fs::create_dir_all(parent)?;
        absolute
    };
    #[cfg(not(windows))]
    let path = {
        fs::create_dir_all(&path)?;
        let path = path.canonicalize()?;
        ensure!(
            fs::read_dir(&path)?.next().is_none(),
            "mount directory must be empty"
        );
        path
    };
    let state = api
        .db
        .canonicalize()?
        .parent()
        .context("missing state directory")?
        .join("mount")
        .join(crate::api::safe_name(email));
    fs::create_dir_all(&state)?;
    let credentials = state.join("credentials.json");
    crate::auth::export_credentials(&credentials_data, &credentials)?;
    let config = state.join("rclone.conf");
    fs::write(&config, "[gdirect]\ntype = drive\nenv_auth = true\n")?;
    let log = state.join("rclone.log");
    #[cfg(unix)]
    let mut command = {
        if foreground {
            Command::new("rclone")
        } else {
            let mut cmd = Command::new("nohup");
            cmd.arg("rclone");
            cmd
        }
    };
    #[cfg(not(unix))]
    let mut command = Command::new("rclone");
    command
        .arg(if cfg!(target_os = "macos") {
            "nfsmount"
        } else {
            "mount"
        })
        .arg("gdirect:")
        .arg(&path)
        .arg("--config")
        .arg(&config)
        .env("GOOGLE_APPLICATION_CREDENTIALS", &credentials)
        .args([
            "--vfs-cache-mode",
            "full",
            "--vfs-cache-max-size",
            "5G",
            "--dir-cache-time",
            "1m",
            "--poll-interval",
            "30s",
            "--file-perms",
            "0600",
            "--dir-perms",
            "0700",
        ])
        .arg("--transfers")
        .arg(connections.to_string())
        .arg("--vfs-read-chunk-streams")
        .arg(connections.to_string())
        .args(["--vfs-read-chunk-size", "4M"])
        .arg("--cache-dir")
        .arg(state.join("cache"))
        .arg("--log-file")
        .arg(&log)
        .args(["--log-level", "INFO"]);
    if read_only {
        command.arg("--read-only");
    }
    println!(
        "Mount: {}\nAccount: {email}\nLog: {}",
        path.display(),
        log.display()
    );
    if foreground || cfg!(windows) {
        let status = command.status();
        let _ = fs::remove_file(&credentials);
        let status = status?;
        ensure!(
            status.success(),
            "rclone mount failed; see {}",
            log.display()
        );
        return Ok(());
    }
    #[cfg(unix)]
    {
        use std::os::unix::process::CommandExt;
        command.process_group(0);
    }
    let log_file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&log)?;
    let mut child = command
        .stdin(Stdio::null())
        .stdout(log_file.try_clone()?)
        .stderr(log_file)
        .spawn()?;
    let mounted = Mounted {
        path,
        pid: child.id(),
        config,
    };
    db.set(&key, &serde_json::to_string(&mounted)?)?;
    for _ in 0..60 {
        if let Some(status) = child.try_wait()? {
            db.unset(&key)?;
            let _ = fs::remove_file(&credentials);
            anyhow::bail!("rclone mount exited ({status}); see {}", log.display());
        }
        if is_mounted(&mounted.path)? {
            println!("Mounted. Use gdirect unmount to detach.");
            return Ok(());
        }
        std::thread::sleep(Duration::from_millis(500));
    }
    child.kill()?;
    child.wait()?;
    // Keep the record if the OS mounted at the timeout boundary.
    if !is_mounted(&mounted.path)? {
        db.unset(&key)?;
        let _ = fs::remove_file(&credentials);
    }
    anyhow::bail!(
        "mount did not become ready within 30s; see {}",
        log.display()
    )
}
fn is_mounted(path: &Path) -> Result<bool> {
    let result = Command::new("mount").output()?;
    ensure!(
        result.status.success(),
        "cannot inspect mounted filesystems"
    );
    let marker = format!(" on {} ", path.display());
    Ok(String::from_utf8_lossy(&result.stdout)
        .lines()
        .any(|line| line.contains(&marker)))
}
/// The account whose mount `unmount` detaches: the one asked for, else the
/// default account's mount, else the only mount recorded.
fn mounted_account(db: &Store, asked: Option<&str>) -> Result<String> {
    if let Some(account) = asked {
        return Ok(account.to_owned());
    }
    let mounted = db.mounted_accounts()?;
    if let Some(default) = db.default_account()?
        && mounted.contains(&default)
    {
        return Ok(default);
    }
    match mounted.as_slice() {
        [one] => Ok(one.clone()),
        [] => anyhow::bail!("no background mount recorded; foreground mounts stop with Ctrl-C"),
        many => anyhow::bail!(
            "several accounts are mounted ({}); choose one with --account",
            many.join(", ")
        ),
    }
}
pub fn unmount(db: &Store, account: Option<&str>) -> Result<()> {
    let account = mounted_account(db, account)?;
    let key = Store::mount_key(&account);
    let raw = db.setting(&key)?.with_context(|| {
        format!("no background mount recorded for {account}; foreground mounts stop with Ctrl-C")
    })?;
    let mounted: Mounted = serde_json::from_str(&raw)?;
    if is_mounted(&mounted.path)? {
        let status = if cfg!(target_os = "macos") {
            Command::new("diskutil")
                .arg("unmount")
                .arg(&mounted.path)
                .status()?
        } else {
            Command::new("fusermount3")
                .arg("-u")
                .arg(&mounted.path)
                .status()?
        };
        ensure!(
            status.success(),
            "unmount failed; close files using the mounted directory and retry"
        );
    }
    #[cfg(unix)]
    {
        // Avoid signalling a reused PID after a crash or reboot.
        let process = Command::new("ps")
            .args(["-p", &mounted.pid.to_string(), "-o", "command="])
            .output()?;
        let command = String::from_utf8_lossy(&process.stdout);
        if command.contains("rclone") && command.contains(mounted.config.to_string_lossy().as_ref())
        {
            let status = Command::new("kill")
                .args(["-TERM", &mounted.pid.to_string()])
                .status()?;
            ensure!(status.success(), "could not stop mount process");
        }
    }
    db.unset(&key)?;
    // rclone was given a copy of the refresh credential; do not leave it behind.
    let _ = fs::remove_file(mounted.config.with_file_name("credentials.json"));
    println!(
        "Unmounted {}. Cached writes are retained for the next mount.",
        mounted.path.display()
    );
    Ok(())
}
